function bbs_designer_setting(string $key): string { $row=db_row('SELECT SettingValue FROM BBS_Settings WHERE SettingKey=? LIMIT 1',[$key]);return(string)($row['SettingValue']??'0'); }
function bbs_designer_runtime_settings(array $rows): array { $values=[];foreach($rows as $row)$values[(string)$row['SettingKey']]=(string)$row['SettingValue'];return['stagedAdminOnly'=>($values['staged_admin_only']??'0')==='1','pilotScopeOnly'=>($values['pilot_scope_only']??'0')==='1','designerEnabled'=>($values['visual_card_designer_enabled']??'0')==='1','renderingEnabled'=>($values['visual_card_designer_rendering_enabled']??'0')==='1']; }
function bbs_designer_require_enabled(): void { if(bbs_designer_setting('visual_card_designer_enabled')!=='1')json_response(['success'=>false,'code'=>'BBS_DESIGNER_DISABLED','message'=>'Visual Card Designer is disabled.'],409); }
function bbs_designer_kind_info(string $value): array { $kind=bbs_designer_kind($value);return$kind==='Personal'?['kind'=>$kind,'parentTable'=>'BBS_Card_Templates','parentColumn'=>'PersonalTemplateID','storageClass'=>'PersonalTemplate']:['kind'=>$kind,'parentTable'=>'BBS_Department_Card_Templates','parentColumn'=>'DepartmentTemplateID','storageClass'=>'DepartmentTemplate']; }
function bbs_designer_asset_dir(): string { $dir=dirname(__DIR__,2).'/backend/private-uploads/bbs-card-designer';if(!is_dir($dir))mkdir($dir,0770,true);return$dir; }
function bbs_designer_asset_payload(array $row): array { return['id'=>(int)$row['id'],'assetKey'=>$row['AssetKey'],'originalName'=>$row['OriginalName'],'mimeType'=>$row['MimeType'],'fileSize'=>(int)$row['FileSize'],'pixelWidth'=>$row['PixelWidth']===null?null:(int)$row['PixelWidth'],'pixelHeight'=>$row['PixelHeight']===null?null:(int)$row['PixelHeight'],'status'=>$row['Status']]; }
function bbs_designer_upload_asset(string $field): array { $file=$_FILES[$field]??null;if(!is_array($file)||(int)($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)json_response(['success'=>false,'message'=>'A JPG, PNG, or WebP designer image is required.'],400);if((int)($file['size']??0)>10*1024*1024)json_response(['success'=>false,'message'=>'Designer image must not exceed 10 MB.'],400);$mime=bbs_card_file_mime((string)$file['tmp_name']);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true))json_response(['success'=>false,'message'=>'Designer image content must be JPEG, PNG, or WebP.'],400);$ext=['image/jpeg'=>'.jpg','image/png'=>'.png','image/webp'=>'.webp'][$mime];$stored=time().'-'.bin2hex(random_bytes(18)).$ext;$target=bbs_designer_asset_dir().'/'.basename($stored);if(!move_uploaded_file((string)$file['tmp_name'],$target))json_response(['success'=>false,'message'=>'Unable to store designer image.'],500);return['stored'=>$stored,'target'=>$target,'name'=>bbs_card_clean($file['name']??'image',255),'mime'=>$mime,'size'=>(int)$file['size']]; }
function bbs_designer_row_layout(array $version,array $sides,array $elements,array $assets=[]): array {
    $layout=['templateKind'=>$version['TemplateKind'],'widthMM'=>(float)$version['WidthMM'],'heightMM'=>(float)$version['HeightMM'],'dpi'=>(int)$version['DPI'],'duplexFlip'=>$version['DuplexFlip'],'backRotation'=>(int)$version['BackRotation'],'sides'=>[],'elements'=>[]];
    $assetIdByName=[];foreach($assets as$asset)$assetIdByName[(string)$asset['StoredName']]=(int)$asset['id'];
    foreach($sides as$row)$layout['sides'][]=['side'=>$row['Side'],'storageClass'=>$row['StorageClass'],'backgroundAssetId'=>$row['StorageClass']==='DesignerAsset'?($assetIdByName[(string)$row['BackgroundStoredName']]??null):null,'backgroundStoredName'=>$row['StorageClass']==='DesignerAsset'?'asset-reference':'parent-reference','backgroundOriginalName'=>$row['BackgroundOriginalName'],'backgroundMimeType'=>$row['BackgroundMimeType'],'backgroundFileSize'=>(int)$row['BackgroundFileSize'],'pixelWidth'=>$row['PixelWidth']===null?null:(int)$row['PixelWidth'],'pixelHeight'=>$row['PixelHeight']===null?null:(int)$row['PixelHeight'],'backgroundFit'=>$row['BackgroundFit'],'backgroundPositionXBP'=>(int)$row['BackgroundPositionXBP'],'backgroundPositionYBP'=>(int)$row['BackgroundPositionYBP'],'bleedMM'=>(float)$row['BleedMM'],'safeMarginMM'=>(float)$row['SafeMarginMM']];
    foreach($elements as$row)$layout['elements'][]=['elementKey'=>$row['ElementKey'],'side'=>$row['Side'],'elementType'=>$row['ElementType'],'dataSourceKey'=>$row['DataSourceKey'],'staticText'=>$row['StaticText'],'assetId'=>$row['AssetID']===null?null:(int)$row['AssetID'],'xBP'=>(int)$row['XBP'],'yBP'=>(int)$row['YBP'],'widthBP'=>(int)$row['WidthBP'],'heightBP'=>(int)$row['HeightBP'],'rotationDeg'=>(float)$row['RotationDeg'],'zIndex'=>(int)$row['ZIndex'],'visible'=>(bool)$row['Visible'],'locked'=>(bool)$row['Locked'],'required'=>(bool)$row['Required'],'style'=>json_decode((string)($row['StyleJSON']??'{}'),true)?:[]];
    $version['id']=(int)$version['id'];$version['VersionNo']=(int)$version['VersionNo'];$version['RowVersion']=(int)$version['RowVersion'];$version['layout']=$layout;$version['assets']=array_map('bbs_designer_asset_payload',$assets);$version['readiness']=bbs_designer_readiness($layout);return$version;
