function bbs_designer_detail(int $id,?PDO $pdo=null,bool $lock=false): ?array {
    $pdo=$pdo?:db();$stmt=$pdo->prepare('SELECT * FROM BBS_Card_Layout_Versions WHERE id=?'.($lock?' FOR UPDATE':''));$stmt->execute([$id]);$version=$stmt->fetch();if(!$version)return null;
    $stmt=$pdo->prepare("SELECT * FROM BBS_Card_Layout_Sides WHERE LayoutVersionID=? ORDER BY FIELD(Side,'Front','Back')");$stmt->execute([$id]);$sides=$stmt->fetchAll();
    $stmt=$pdo->prepare("SELECT * FROM BBS_Card_Layout_Elements WHERE LayoutVersionID=? ORDER BY FIELD(Side,'Front','Back'),ZIndex,id");$stmt->execute([$id]);$elements=$stmt->fetchAll();
    $stmt=$pdo->prepare("SELECT * FROM BBS_Card_Layout_Assets WHERE LayoutVersionID=? AND Status='Active' ORDER BY CreatedAt,id");$stmt->execute([$id]);return bbs_designer_row_layout($version,$sides,$elements,$stmt->fetchAll());
}
function bbs_designer_insert_content(PDO $pdo,int $versionId,array $layout): void {
    $side=$pdo->prepare('INSERT INTO BBS_Card_Layout_Sides(LayoutVersionID,Side,StorageClass,BackgroundStoredName,BackgroundOriginalName,BackgroundMimeType,BackgroundFileSize,PixelWidth,PixelHeight,BackgroundFit,BackgroundPositionXBP,BackgroundPositionYBP,BleedMM,SafeMarginMM) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');
    foreach($layout['sides'] as$item)$side->execute([$versionId,$item['side'],$item['storageClass'],$item['backgroundStoredName'],$item['backgroundOriginalName'],$item['backgroundMimeType'],$item['backgroundFileSize'],$item['pixelWidth'],$item['pixelHeight'],$item['backgroundFit'],$item['backgroundPositionXBP'],$item['backgroundPositionYBP'],$item['bleedMM'],$item['safeMarginMM']]);
    $element=$pdo->prepare('INSERT INTO BBS_Card_Layout_Elements(LayoutVersionID,ElementKey,Side,ElementType,DataSourceKey,StaticText,AssetID,XBP,YBP,WidthBP,HeightBP,RotationDeg,ZIndex,Visible,Locked,Required,StyleJSON) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');
    foreach($layout['elements'] as$item)$element->execute([$versionId,$item['elementKey'],$item['side'],$item['elementType'],$item['dataSourceKey'],$item['staticText'],$item['assetId'],$item['xBP'],$item['yBP'],$item['widthBP'],$item['heightBP'],$item['rotationDeg'],$item['zIndex'],$item['visible'],$item['locked'],$item['required'],json_encode($item['style'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);
}
function bbs_designer_legacy_payload(array $parent,array $info): array {
    $personal=$info['kind']==='Personal';$elements=$personal?[
        ['elementKey'=>'employee-name','side'=>'Front','elementType'=>'DynamicText','dataSourceKey'=>'employee.full_name','xBP'=>700,'yBP'=>6500,'widthBP'=>5200,'heightBP'=>900,'zIndex'=>10,'required'=>true,'style'=>['fontSizePt'=>14,'fontWeight'=>'700']],
        ['elementKey'=>'employee-department','side'=>'Front','elementType'=>'DynamicText','dataSourceKey'=>'employee.department','xBP'=>700,'yBP'=>7450,'widthBP'=>5200,'heightBP'=>650,'zIndex'=>11,'required'=>true,'style'=>['fontSizePt'=>9]],
        ['elementKey'=>'employee-position','side'=>'Front','elementType'=>'DynamicText','dataSourceKey'=>'employee.position','xBP'=>700,'yBP'=>8150,'widthBP'=>5200,'heightBP'=>650,'zIndex'=>12,'style'=>['fontSizePt'=>9]],
        ['elementKey'=>'personal-qr','side'=>'Front','elementType'=>'QR','dataSourceKey'=>'card.personal_qr','xBP'=>6800,'yBP'=>6100,'widthBP'=>2500,'heightBP'=>2500,'zIndex'=>20,'required'=>true,'style'=>['objectFit'=>'Contain']],
    ]:[['elementKey'=>'department-qr','side'=>'Front','elementType'=>'QR','dataSourceKey'=>'department.community_qr','xBP'=>6900,'yBP'=>6900,'widthBP'=>2400,'heightBP'=>2400,'zIndex'=>20,'required'=>true,'style'=>['objectFit'=>'Contain']]];
