function bbs_designer_canonicalize_resources(PDO $pdo,array $version,array $layout): array {
    $info=bbs_designer_kind_info((string)$version['TemplateKind']);$parentId=(int)$version[$info['parentColumn']];$stmt=$pdo->prepare("SELECT * FROM {$info['parentTable']} WHERE id=?");$stmt->execute([$parentId]);$parent=$stmt->fetch();if(!$parent)throw new InvalidArgumentException('Parent template was not found.');
    $stmt=$pdo->prepare("SELECT * FROM BBS_Card_Layout_Assets WHERE LayoutVersionID=? AND Status='Active'");$stmt->execute([(int)$version['id']]);$assets=$stmt->fetchAll();$byId=[];foreach($assets as$asset)$byId[(int)$asset['id']]=$asset;
    foreach(array_values(array_unique(array_filter(array_column($layout['elements'],'assetId'))))as$id)if(!isset($byId[(int)$id]))throw new InvalidArgumentException('One or more static assets do not belong to this Draft.');
    foreach($layout['sides']as$index=>$side){if($side['storageClass']===$info['storageClass']){$layout['sides'][$index]=array_merge($side,['backgroundAssetId'=>null,'backgroundStoredName'=>$parent['BackgroundStoredName'],'backgroundOriginalName'=>$parent['OriginalName'],'backgroundMimeType'=>$parent['MimeType'],'backgroundFileSize'=>(int)($parent['FileSize']??0)]);}elseif($side['storageClass']==='DesignerAsset'){$asset=$byId[(int)($side['backgroundAssetId']??0)]??null;if(!$asset)throw new InvalidArgumentException('Designer background must reference an uploaded asset from this Draft.');$layout['sides'][$index]=array_merge($side,['backgroundAssetId'=>(int)$asset['id'],'backgroundStoredName'=>$asset['StoredName'],'backgroundOriginalName'=>$asset['OriginalName'],'backgroundMimeType'=>$asset['MimeType'],'backgroundFileSize'=>(int)$asset['FileSize'],'pixelWidth'=>$asset['PixelWidth']===null?null:(int)$asset['PixelWidth'],'pixelHeight'=>$asset['PixelHeight']===null?null:(int)$asset['PixelHeight']]);}else throw new InvalidArgumentException('Background storage class does not match this template.');}
    return$layout;
}
function bbs_designer_error(Throwable $error): void { if($error instanceof InvalidArgumentException)json_response(['success'=>false,'code'=>'BBS_DESIGNER_VALIDATION_FAILED','message'=>$error->getMessage()],400);if(($error instanceof PDOException)&&($error->errorInfo[1]??null)===1146)json_response(['success'=>false,'code'=>'BBS_DESIGNER_SETUP_REQUIRED','message'=>'BBS Phase 10F-1 database migration is required.'],503);if(($error instanceof PDOException)&&($error->errorInfo[1]??null)===1062)json_response(['success'=>false,'code'=>'VERSION_CONFLICT','message'=>'The layout version conflicts with an existing record.'],409);throw$error; }

