        $ready=route_params($path,'/bbs/admin/card-designer/versions/:id/readiness');if($method==='POST'&&$ready!==null){$id=bbs_phase1_positive_int($ready['id']);if(!$id)throw new InvalidArgumentException('Layout version ID is required.');$row=bbs_designer_detail($id);if(!$row)json_response(['success'=>false,'message'=>'Layout version was not found.'],404);json_response(['success'=>true,'data'=>$row['readiness']]);}
