        $assetFile=route_params($path,'/bbs/admin/card-designer/assets/:assetId/file');if($method==='GET'&&$assetFile!==null){$assetId=bbs_phase1_positive_int($assetFile['assetId']);$row=db_row("SELECT * FROM BBS_Card_Layout_Assets WHERE id=? AND Status='Active'",[$assetId]);if(!$row)json_response(['success'=>false,'message'=>'Designer asset was not found.'],404);$file=bbs_designer_asset_dir().'/'.basename((string)$row['StoredName']);if(!is_file($file)||bbs_card_file_mime($file)!==$row['MimeType'])json_response(['success'=>false,'message'=>'Designer asset file is unavailable.'],404);header('Content-Type: '.$row['MimeType']);header("Content-Disposition: inline; filename*=UTF-8''".rawurlencode((string)$row['OriginalName']));header('Cache-Control: private, no-store');readfile($file);exit;}
        $background=route_params($path,'/bbs/admin/card-designer/versions/:id/sides/:side/background');if($method==='GET'&&$background!==null){$id=bbs_phase1_positive_int($background['id']);$side=strtolower((string)$background['side'])==='back'?'Back':'Front';$row=db_row('SELECT StorageClass,BackgroundStoredName,BackgroundOriginalName,BackgroundMimeType FROM BBS_Card_Layout_Sides WHERE LayoutVersionID=? AND Side=?',[$id,$side]);if(!$row||!in_array($row['StorageClass'],['PersonalTemplate','DepartmentTemplate','DesignerAsset'],true))json_response(['success'=>false,'message'=>'Layout background was not found.'],404);$root=$row['StorageClass']==='DesignerAsset'?bbs_designer_asset_dir():bbs_card_template_dir();$file=$root.'/'.basename((string)$row['BackgroundStoredName']);if(!is_file($file)||bbs_card_file_mime($file)!==$row['BackgroundMimeType'])json_response(['success'=>false,'message'=>'Layout background file is unavailable.'],404);header('Content-Type: '.$row['BackgroundMimeType']);header("Content-Disposition: inline; filename*=UTF-8''".rawurlencode((string)$row['BackgroundOriginalName']));header('Cache-Control: private, no-store');readfile($file);exit;}
        return false;
    }catch(Throwable$e){bbs_designer_error($e);}return true;
}
